.form_label:before {
  content: '';
  display: inline-block;
  border: 5px solid #409EFF;
  border-right-color: transparent;
  border-bottom-color: transparent;
  border-top-color: transparent;
}

.basic_info {
  .info_title {
    font-size: 14px;
    color: #409EFF;
    height: 35px;
    line-height: 35px;
    display: flex;
    align-items: center;
    padding-left: 20px;

    .dev_name {
      font-size: 14px;
      display: inline-block;
      margin: 0 20px;
    }

    .btn_box {
      flex: auto;
      text-align: right;
    }

    img {
      width: 28px;
      height: 28px;
    }
  }

  .info_form {
    position: relative;
    display: flex;
    align-items: center;
    padding-left: 20px;
    flex-direction: row;
    padding-top:30px;
    width: 100%;
    .form_box {
      width: 75%;

      .form_item {
        display: flex;
        flex-direction: row;

        .form_label {
          line-height: 40px;
          font-size: 14px;
          white-space: nowrap;
          position: relative;
        }

        .form_content {
          flex: auto;
          overflow-x: hidden;
          line-height: 40px;
          font-size: 14px;
          padding-left: 15px;
        }
      }
    }

    .code_img_box {
      flex: auto;
      text-align: right;
      white-space: nowrap;

      .qrcode {
        display: inline-block;
        // height: 80px;
        // width: 80px;
      }

      img {
        height: 80px;
        width: 80px;

        &:first-child {
          margin-right: 10px
        }
      }
    }
  }
}


